import threading

views = {"home": 0}
both_have_read = threading.Barrier(2)

def record_view(page):
    current = views[page]
    both_have_read.wait()
    views[page] = current + 1

threads = [threading.Thread(target=record_view, args=("home",))
           for _ in range(2)]
for t in threads: t.start()
for t in threads: t.join()

print("real views:   ", 2)
print("counted views:", views["home"])

import threading

def racy():
    stock = [1]
    sold = []
    gate = threading.Barrier(2)
    def buy(name):
        if stock[0] >= 1:        # check
            gate.wait()
            stock[0] -= 1        # act
            sold.append(name)
    ts = [threading.Thread(target=buy, args=(n,)) for n in ("Ana", "Ben")]
    for t in ts: t.start()
    for t in ts: t.join()
    return len(sold), stock[0]

lock = threading.Lock()

def safe():
    stock = [1]
    sold, turned_away = [], []
    def buy(name):
        with lock:               # check and act inside one critical section
            if stock[0] >= 1:
                stock[0] -= 1
                sold.append(name)
            else:
                turned_away.append(name)
    ts = [threading.Thread(target=buy, args=(n,)) for n in ("Ana", "Ben")]
    for t in ts: t.start()
    for t in ts: t.join()
    return len(sold), stock[0], len(turned_away)

print("racy:  sold / stock left =", racy())
print("safe:  sold / stock left / turned away =", safe())

import os, tempfile, threading

base = tempfile.mkdtemp()
outdir = os.path.join(base, "build-output")
gate = threading.Barrier(2)
outcomes = {}

def deploy(name):
    if not os.path.exists(outdir):   # both observe: does not exist
        gate.wait()
        try:
            os.makedirs(outdir)      # only one can win the creation
            outcomes[name] = "created it"
        except FileExistsError:
            outcomes[name] = "FileExistsError"

threads = [threading.Thread(target=deploy, args=(n,)) for n in ("S1", "S2")]
for t in threads: t.start()
for t in threads: t.join()
print("outcomes across both scripts:", sorted(outcomes.values()))

# the standard fix: state the intent, don't pre-check it
outcomes2 = {}
def deploy2(name):
    os.makedirs(outdir, exist_ok=True)
    outcomes2[name] = "ok"

threads = [threading.Thread(target=deploy2, args=(n,)) for n in ("S1", "S2")]
for t in threads: t.start()
for t in threads: t.join()
print("with exist_ok=True:         ", sorted(outcomes2.values()))

import queue, threading

q = queue.Queue()
q.put("job-1")
gate = threading.Barrier(2)
results = {}

def consumer(name, goes_first):
    if not q.empty():                    # both consumers see: not empty
        gate.wait()
        if not goes_first:
            took.wait()
        try:
            results[name] = "got " + q.get_nowait()
        except queue.Empty:
            results[name] = "queue.Empty raised"
        if goes_first:
            took.set()

took = threading.Event()
threads = [threading.Thread(target=consumer, args=("C1", True)),
           threading.Thread(target=consumer, args=("C2", False))]
for t in threads: t.start()
for t in threads: t.join()
for name in sorted(results):
    print(name, "->", results[name])

import threading

def racy_register():
    users = {}
    gate = threading.Barrier(2)
    confirmations = []
    def register(name):
        if name not in users:          # both requests pass the check
            gate.wait()
            users[name] = {"name": name}
            confirmations.append(name) # both callers get a success
    ts = [threading.Thread(target=register, args=("sam",)) for _ in range(2)]
    for t in ts: t.start()
    for t in ts: t.join()
    return len(confirmations), len(users)

lock = threading.Lock()

def safe_register():
    users = {}
    outcomes = []
    def register(name):
        with lock:                     # check + insert are one step
            if name not in users:
                users[name] = {"name": name}
                outcomes.append("created")
            else:
                outcomes.append("rejected: name taken")
    ts = [threading.Thread(target=register, args=("sam",)) for _ in range(2)]
    for t in ts: t.start()
    for t in ts: t.join()
    return sorted(outcomes), len(users)

print("racy: confirmations sent / rows stored =", racy_register())
print("safe: outcomes / rows stored =", safe_register())

import threading

plain = threading.Lock()

def inner_plain():
    with plain:            # blocks forever: the lock is already held...
        return "inner ran"

def outer_plain():
    with plain:            # ...by THIS thread. A Lock doesn't care who asks.
        return inner_plain()

t = threading.Thread(target=outer_plain, daemon=True)
t.start()
t.join(timeout=0.5)
print("plain Lock:  outer call finished =", not t.is_alive())

reentrant = threading.RLock()

def inner_re():
    with reentrant:
        return "inner ran"

def outer_re():
    with reentrant:
        return inner_re()

print("RLock:       outer call returned =", outer_re())

import threading

class Cache:
    def __init__(self):
        self.lock = threading.Lock()
        self.data = {}
    def get(self, key, validator=None):
        with self.lock:                       # lock held...
            if validator is not None:
                validator(self)               # ...while running foreign code
            return self.data.get(key)

cache = Cache()
cache.data["settings"] = "v1"

def my_validator(c):
    return c.get("settings")                  # re-enters get(): needs the lock

t = threading.Thread(target=lambda: cache.get("profile", my_validator),
                     daemon=True)
t.start()
t.join(timeout=0.5)
print("cache with callback under lock: finished =", not t.is_alive())

class Cache2:
    def __init__(self):
        self.lock = threading.Lock()
        self.data = {}
    def get(self, key, validator=None):
        if validator is not None:
            validator(self)                   # foreign code runs lock-free
        with self.lock:
            return self.data.get(key)

cache2 = Cache2()
cache2.data["settings"] = "v1"
print("validator outside the lock:     finished =",
      cache2.get("profile", my_validator) is None or True)

import threading

jobs = ["job-1", "job-2"]
results = []                       # appended in COMPLETION order
job2_finished = threading.Event()

def run(job, is_job2):
    if not is_job2:
        job2_finished.wait()       # force job-1 to finish second
    results.append(job.upper() + "-DONE")
    if is_job2:
        job2_finished.set()

threads = [threading.Thread(target=run, args=("job-1", False)),
           threading.Thread(target=run, args=("job-2", True))]
for t in threads: t.start()
for t in threads: t.join()

