import threading

partials = {}
lock = threading.Lock()
barrier = threading.Barrier(3)
totals_seen = {}

def worker(name, values):
    with lock:
        partials[name] = sum(values)
    barrier.wait()                    # nobody proceeds until ALL parts exist
    totals_seen[name] = sum(partials.values())

threads = [threading.Thread(target=worker, args=("W1", (1, 2, 3))),
           threading.Thread(target=worker, args=("W2", (10, 20))),
           threading.Thread(target=worker, args=("W3", (100,)))]
for t in threads: t.start()
for t in threads: t.join()
print("partials:", {k: partials[k] for k in sorted(partials)})
print("total seen by every worker:", sorted(set(totals_seen.values())))

# and when one worker dies before the rendezvous:
barrier2 = threading.Barrier(3)
broken = []
def doomed(name, fail=False):
    try:
        if fail:
            barrier2.abort()          # a dead participant must break the barrier
            raise RuntimeError("worker died")
        barrier2.wait()
    except threading.BrokenBarrierError:
        broken.append(name)
    except RuntimeError:
        pass

threads = [threading.Thread(target=doomed, args=("W1",)),
           threading.Thread(target=doomed, args=("W2",)),
           threading.Thread(target=doomed, args=("W3", True))]
for t in threads: t.start()
for t in threads: t.join()
print("workers released with BrokenBarrierError:", sorted(broken))

