import threading

class Service:
    pass

box = {"instance": None}
constructions = [0]
gate = threading.Barrier(2)

def get_instance():
    if box["instance"] is None:        # both threads see None
        gate.wait()
        constructions[0] += 1
        mine = Service()                # each builds its own
        box["instance"] = mine
        return mine                     # and returns the one IT built
    return box["instance"]

got = {}
def run(tag):
    got[tag] = get_instance()

threads = [threading.Thread(target=run, args=(tag,)) for tag in ("T1", "T2")]
for t in threads: t.start()
for t in threads: t.join()

print("objects constructed:        ", constructions[0])
print("callers share one object:   ", got["T1"] is got["T2"])
