import queue, threading

inbox = queue.Queue()
chunks = {"chunk-0": (1, 2), "chunk-1": (3, 4), "chunk-2": (5, 6)}

def worker(chunk_id, numbers):
    total = sum(numbers)                 # the work happens privately
    inbox.put((chunk_id, total))         # identity travels WITH the result

threads = [threading.Thread(target=worker, args=(cid, nums))
           for cid, nums in sorted(chunks.items())]
for t in threads: t.start()
for t in threads: t.join()

results = {}
while not inbox.empty():
    chunk_id, total = inbox.get()
    results[chunk_id] = total

print("results by chunk:", {k: results[k] for k in sorted(results)})
print("grand total:     ", sum(results.values()))

import threading

order = {"status": "paid"}
lock = threading.Lock()
outcomes = {}

def transition(name, target, goes_first):
    if not goes_first:
        first_done.wait()
    with lock:                              # check-and-set, indivisible
        if order["status"] == "paid":
            order["status"] = target
            outcomes[name] = f"{target}: success"
        else:
            outcomes[name] = f"{target}: rejected - already {order['status']}"
    if goes_first:
        first_done.set()

first_done = threading.Event()
t1 = threading.Thread(target=transition, args=("admin-1", "shipped", True))
t2 = threading.Thread(target=transition, args=("admin-2", "cancelled", False))
t1.start(); t2.start()
t1.join(); t2.join()

print("final status:", order["status"])
for name in sorted(outcomes):
    print(" ", name, "->", outcomes[name])

import threading

def trial(n):
    counter = [0]
    gate = threading.Barrier(n)
    def add_one():
        seen = counter[0]
        gate.wait()                 # all n threads read before any writes
        counter[0] = seen + 1
    ts = [threading.Thread(target=add_one) for _ in range(n)]
    for t in ts: t.start()
    for t in ts: t.join()
    return counter[0]

for n in (2, 4, 8, 16):
    print(f"workers: {n:2d}   expected: {n:2d}   counter says: {trial(n)}")
